function cipherWindow(text, pattern) {
  const covers = (s) => {
    const counts = new Array(26).fill(0);
    for (const ch of s) counts[ch.charCodeAt(0) - 97]++;
    for (const ch of pattern) if (--counts[ch.charCodeAt(0) - 97] < 0) return false;
    return true;
  };
  for (let len = pattern.length; len <= text.length; len++)
    for (let s = 0; s + len <= text.length; s++)
      if (covers(text.slice(s, s + len))) return text.slice(s, s + len);
  return '';
}

function cipherWindow(text, pattern) {
  const need = new Array(26).fill(0);
  for (const ch of pattern) need[ch.charCodeAt(0) - 97]++;
  let missing = pattern.length, left = 0, bestStart = 0, bestLength = Infinity;
  for (let right = 0; right < text.length; right++) {
    if (need[text.charCodeAt(right) - 97]-- > 0) missing--;
    while (missing === 0) {
      if (right - left + 1 < bestLength) { bestLength = right - left + 1; bestStart = left; }
      if (++need[text.charCodeAt(left) - 97] > 0) missing++;
      left++;
    }
  }
  return bestLength === Infinity ? '' : text.slice(bestStart, bestStart + bestLength);
}
